SELECT "TableroSistemaPenal_8"."Number_of_Records" AS "Number_of_Records",   "TableroSistemaPenal_8"."PAIS" AS "PAIS",   "TableroSistemaPenal_8"."Tipo_Sentencia" AS "Tipo_Sentencia",   SUM(CAST("TableroSistemaPenal_8"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok" FROM "TableroSistemaPenal_8" WHERE ("TableroSistemaPenal_8"."Tipo_Sentencia" IN ('Sentencia Absolutoria', 'Sentencia Condenatoria')) GROUP BY "TableroSistemaPenal_8"."Number_of_Records",   "TableroSistemaPenal_8"."PAIS", "TableroSistemaPenal_8"."Tipo_Sentencia";
